import java.util.Scanner;

public class Main {
    static long[] a = new long[20];

    static long solve_variant(long n) {
        if (n == 0) return 0;
        int i = 0;
        for (i = 1; i <= 16; ++i) {
            if (a[i] > n) break;
        }
        long cost1 = (long)1e18, cost2 = (long)1e18;
        cost1 = (n / a[i - 1]) * (i - 1) + solve_variant(n % a[i - 1]);
        if (a[i] - n < n)
            cost2 = i + solve_variant(a[i] - n);
        return Math.min(cost1, cost2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        for (int i = 1; i <= 16; ++i)
            a[i] = a[i - 1] * 10 + 1;
        long number = scanner.nextLong();
        System.out.println(solve_variant(number));
        scanner.close();
    }
}

